const CURRY_TTL = "# The curry ontology — a small OWL ontology for teaching, modelled on the\n# Manchester pizza ontology (Horridge et al.). Part of Scopoli · MAM04.\n# Open it in (Web)Protégé, or query it with SPARQL.\n#\n# Curries are classes (kinds of dish), not individuals: \"every Massaman curry\n# has some beef\" is a restriction on the class MassamanCurry. The only\n# individuals are countries.\n\n@prefix :     <https://koetai.github.io/scopoli-mam04/curry#> .\n@prefix cur:  <https://koetai.github.io/scopoli-mam04/curry#> .\n@prefix owl:  <http://www.w3.org/2002/07/owl#> .\n@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .\n@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .\n@prefix skos: <http://www.w3.org/2004/02/skos/core#> .\n@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .\n@prefix dct:  <http://purl.org/dc/terms/> .\n\n<https://koetai.github.io/scopoli-mam04/curry> a owl:Ontology ;\n    rdfs:label \"The curry ontology\"@en , \"De curry-ontologie\"@nl ;\n    rdfs:comment \"A small teaching ontology of curries, their bases and ingredients, modelled on the pizza ontology.\"@en ;\n    owl:versionInfo \"2026-11-18\" ;\n    dct:license <https://creativecommons.org/licenses/by/4.0/> .\n\n# ------------------------------------------------------------------ properties\n\n:hasIngredient a owl:ObjectProperty , owl:TransitiveProperty ;\n    rdfs:label \"has ingredient\"@en , \"heeft ingrediënt\"@nl ;\n    rdfs:comment \"Anything that goes into a dish. Transitive: an ingredient of the base is an ingredient of the curry.\"@en ;\n    owl:inverseOf :isIngredientOf ;\n    rdfs:domain :Food ;\n    rdfs:range :Food .\n\n:isIngredientOf a owl:ObjectProperty , owl:TransitiveProperty ;\n    rdfs:label \"is ingredient of\"@en , \"is ingrediënt van\"@nl .\n\n:hasBase a owl:ObjectProperty , owl:FunctionalProperty ;\n    rdfs:subPropertyOf :hasIngredient ;\n    rdfs:label \"has base\"@en , \"heeft basis\"@nl ;\n    rdfs:comment \"The sauce a curry is built on. Functional: a curry has at most one base.\"@en ;\n    rdfs:domain :Curry ;\n    rdfs:range :CurryBase .\n\n:hasMainIngredient a owl:ObjectProperty ;\n    rdfs:subPropertyOf :hasIngredient ;\n    rdfs:label \"has main ingredient\"@en , \"heeft hoofdingrediënt\"@nl ;\n    rdfs:comment \"What is cooked in the base: meat, fish, vegetables, nuts, dairy, spices.\"@en ;\n    rdfs:domain :Curry ;\n    rdfs:range :CurryIngredient .\n\n:hasCountryOfOrigin a owl:ObjectProperty ;\n    rdfs:label \"has country of origin\"@en , \"heeft land van herkomst\"@nl ;\n    rdfs:range :Country .\n\n# --------------------------------------------------------------- top classes\n\n:Food a owl:Class ;\n    rdfs:label \"food\"@en , \"voedsel\"@nl .\n\n:Curry a owl:Class ;\n    rdfs:subClassOf :Food ,\n        [ a owl:Restriction ; owl:onProperty :hasBase ; owl:someValuesFrom :CurryBase ] ;\n    rdfs:label \"curry\"@en , \"curry\"@nl ;\n    rdfs:comment \"A dish of meat, fish, vegetables or pulses cooked in a spiced sauce.\"@en .\n\n:CurryBase a owl:Class ;\n    rdfs:subClassOf :Food ;\n    rdfs:label \"curry base\"@en , \"currybasis\"@nl ;\n    rdfs:comment \"The sauce a curry is built on.\"@en .\n\n:CurryIngredient a owl:Class ;\n    rdfs:subClassOf :Food ;\n    rdfs:label \"curry ingredient\"@en , \"curry-ingrediënt\"@nl .\n\n:Country a owl:Class ;\n    rdfs:label \"country\"@en , \"land\"@nl .\n\n[] a owl:AllDisjointClasses ; owl:members ( :Curry :CurryBase :CurryIngredient :Country ) .\n\n# --------------------------------------------------------------------- bases\n\n:CoconutMilkBase a owl:Class ; rdfs:subClassOf :CurryBase ;\n    rdfs:label \"coconut milk base\"@en , \"kokosmelkbasis\"@nl .\n\n:YoghurtBase a owl:Class ; rdfs:subClassOf :CurryBase ;\n    rdfs:label \"yoghurt base\"@en , \"yoghurtbasis\"@nl .\n\n:TomatoBase a owl:Class ; rdfs:subClassOf :CurryBase ;\n    rdfs:label \"tomato base\"@en , \"tomatenbasis\"@nl .\n\n:LentilBase a owl:Class ; rdfs:subClassOf :CurryBase ;\n    rdfs:label \"lentil base\"@en , \"linzenbasis\"@nl .\n\n:RouxBase a owl:Class ;\n    rdfs:subClassOf :CurryBase ,\n        [ a owl:Restriction ; owl:onProperty :hasIngredient ; owl:someValuesFrom :WheatFlourIngredient ] ;\n    rdfs:label \"roux base\"@en , \"rouxbasis\"@nl ;\n    rdfs:comment \"Fat and wheat flour cooked together, sold in Japan as curry roux blocks.\"@en .\n\n[] a owl:AllDisjointClasses ;\n    owl:members ( :CoconutMilkBase :YoghurtBase :TomatoBase :LentilBase :RouxBase ) .\n\n# --------------------------------------------------------------- ingredients\n\n:MeatIngredient a owl:Class ; rdfs:subClassOf :CurryIngredient ;\n    rdfs:label \"meat\"@en , \"vlees\"@nl .\n:ChickenIngredient a owl:Class ; rdfs:subClassOf :MeatIngredient ;\n    rdfs:label \"chicken\"@en , \"kip\"@nl .\n:BeefIngredient a owl:Class ; rdfs:subClassOf :MeatIngredient ;\n    rdfs:label \"beef\"@en , \"rundvlees\"@nl .\n:LambIngredient a owl:Class ; rdfs:subClassOf :MeatIngredient ;\n    rdfs:label \"lamb\"@en , \"lamsvlees\"@nl .\n:PorkIngredient a owl:Class ; rdfs:subClassOf :MeatIngredient ;\n    rdfs:label \"pork\"@en , \"varkensvlees\"@nl .\n\n:SeafoodIngredient a owl:Class ; rdfs:subClassOf :CurryIngredient ;\n    rdfs:label \"fish and seafood\"@en , \"vis en zeevruchten\"@nl .\n:PrawnIngredient a owl:Class ; rdfs:subClassOf :SeafoodIngredient ;\n    rdfs:label \"prawn\"@en , \"garnaal\"@nl .\n:FishSauceIngredient a owl:Class ; rdfs:subClassOf :SeafoodIngredient ;\n    rdfs:label \"fish sauce\"@en , \"vissaus\"@nl ;\n    rdfs:comment \"Fermented fish; used for salt in most Thai curries.\"@en .\n\n:VegetableIngredient a owl:Class ; rdfs:subClassOf :CurryIngredient ;\n    rdfs:label \"vegetable\"@en , \"groente\"@nl .\n:PotatoIngredient a owl:Class ; rdfs:subClassOf :VegetableIngredient ;\n    rdfs:label \"potato\"@en , \"aardappel\"@nl .\n:AubergineIngredient a owl:Class ; rdfs:subClassOf :VegetableIngredient ;\n    rdfs:label \"aubergine\"@en , \"aubergine\"@nl ; skos:altLabel \"eggplant\"@en .\n:OnionIngredient a owl:Class ; rdfs:subClassOf :VegetableIngredient ;\n    rdfs:label \"onion\"@en , \"ui\"@nl .\n:BambooShootIngredient a owl:Class ; rdfs:subClassOf :VegetableIngredient ;\n    rdfs:label \"bamboo shoot\"@en , \"bamboescheut\"@nl .\n:CarrotIngredient a owl:Class ; rdfs:subClassOf :VegetableIngredient ;\n    rdfs:label \"carrot\"@en , \"wortel\"@nl .\n\n:NutIngredient a owl:Class ; rdfs:subClassOf :CurryIngredient ;\n    rdfs:label \"nut\"@en , \"noot\"@nl .\n:PeanutIngredient a owl:Class ; rdfs:subClassOf :NutIngredient ;\n    rdfs:label \"peanut\"@en , \"pinda\"@nl ;\n    rdfs:comment \"Botanically a legume, not a nut; filed under nuts here, as cooks and allergy labels do.\"@en .\n:CashewIngredient a owl:Class ; rdfs:subClassOf :NutIngredient ;\n    rdfs:label \"cashew\"@en , \"cashewnoot\"@nl .\n:AlmondIngredient a owl:Class ; rdfs:subClassOf :NutIngredient ;\n    rdfs:label \"almond\"@en , \"amandel\"@nl .\n\n:DairyIngredient a owl:Class ; rdfs:subClassOf :CurryIngredient ;\n    rdfs:label \"dairy\"@en , \"zuivel\"@nl .\n:CreamIngredient a owl:Class ; rdfs:subClassOf :DairyIngredient ;\n    rdfs:label \"cream\"@en , \"room\"@nl .\n:ButterIngredient a owl:Class ; rdfs:subClassOf :DairyIngredient ;\n    rdfs:label \"butter\"@en , \"boter\"@nl .\n:GheeIngredient a owl:Class ; rdfs:subClassOf :DairyIngredient ;\n    rdfs:label \"ghee\"@en , \"ghee\"@nl ; rdfs:comment \"Clarified butter.\"@en .\n:CheeseIngredient a owl:Class ; rdfs:subClassOf :DairyIngredient ;\n    rdfs:label \"cheese\"@en , \"kaas\"@nl .\n:PaneerIngredient a owl:Class ; rdfs:subClassOf :CheeseIngredient ;\n    rdfs:label \"paneer\"@en , \"paneer\"@nl ; rdfs:comment \"Fresh Indian cheese that does not melt.\"@en .\n\n:SpiceIngredient a owl:Class ; rdfs:subClassOf :CurryIngredient ;\n    rdfs:label \"spice\"@en , \"specerij\"@nl .\n:ChilliIngredient a owl:Class ; rdfs:subClassOf :SpiceIngredient ;\n    rdfs:label \"chilli\"@en , \"chilipeper\"@nl .\n:TurmericIngredient a owl:Class ; rdfs:subClassOf :SpiceIngredient ;\n    rdfs:label \"turmeric\"@en , \"kurkuma\"@nl .\n:CuminIngredient a owl:Class ; rdfs:subClassOf :SpiceIngredient ;\n    rdfs:label \"cumin\"@en , \"komijn\"@nl .\n:GaramMasalaIngredient a owl:Class ; rdfs:subClassOf :SpiceIngredient ;\n    rdfs:label \"garam masala\"@en , \"garam masala\"@nl ; rdfs:comment \"A blend of ground spices.\"@en .\n:CurryPasteIngredient a owl:Class ; rdfs:subClassOf :SpiceIngredient ;\n    rdfs:label \"curry paste\"@en , \"currypasta\"@nl .\n:GreenCurryPasteIngredient a owl:Class ; rdfs:subClassOf :CurryPasteIngredient ;\n    rdfs:label \"green curry paste\"@en , \"groene currypasta\"@nl .\n:RedCurryPasteIngredient a owl:Class ; rdfs:subClassOf :CurryPasteIngredient ;\n    rdfs:label \"red curry paste\"@en , \"rode currypasta\"@nl .\n\n:GrainIngredient a owl:Class ; rdfs:subClassOf :CurryIngredient ;\n    rdfs:label \"grain\"@en , \"graan\"@nl .\n:WheatFlourIngredient a owl:Class ; rdfs:subClassOf :GrainIngredient ;\n    rdfs:label \"wheat flour\"@en , \"tarwebloem\"@nl ; rdfs:comment \"Contains gluten.\"@en .\n\n[] a owl:AllDisjointClasses ;\n    owl:members ( :MeatIngredient :SeafoodIngredient :VegetableIngredient :NutIngredient\n                  :DairyIngredient :SpiceIngredient :GrainIngredient ) .\n\n# ----------------------------------------------------------------- countries\n\n:Thailand a owl:NamedIndividual , :Country ; rdfs:label \"Thailand\"@en , \"Thailand\"@nl .\n:India a owl:NamedIndividual , :Country ; rdfs:label \"India\"@en , \"India\"@nl .\n:Japan a owl:NamedIndividual , :Country ; rdfs:label \"Japan\"@en , \"Japan\"@nl .\n:UnitedKingdom a owl:NamedIndividual , :Country ; rdfs:label \"United Kingdom\"@en , \"Verenigd Koninkrijk\"@nl .\n\n[] a owl:AllDifferent ; owl:distinctMembers ( :Thailand :India :Japan :UnitedKingdom ) .\n\n# -------------------------------------------------------------- named curries\n\n:NamedCurry a owl:Class ; rdfs:subClassOf :Curry ;\n    rdfs:label \"named curry\"@en , \"benoemde curry\"@nl ;\n    rdfs:comment \"A curry with a recognised recipe.\"@en .\n\n:GreenCurry a owl:Class ;\n    rdfs:subClassOf :NamedCurry ,\n        [ a owl:Restriction ; owl:onProperty :hasBase ; owl:someValuesFrom :CoconutMilkBase ] ,\n        [ a owl:Restriction ; owl:onProperty :hasMainIngredient ; owl:someValuesFrom :ChickenIngredient ] ,\n        [ a owl:Restriction ; owl:onProperty :hasMainIngredient ; owl:someValuesFrom :AubergineIngredient ] ,\n        [ a owl:Restriction ; owl:onProperty :hasMainIngredient ; owl:someValuesFrom :BambooShootIngredient ] ,\n        [ a owl:Restriction ; owl:onProperty :hasMainIngredient ; owl:someValuesFrom :GreenCurryPasteIngredient ] ,\n        [ a owl:Restriction ; owl:onProperty :hasMainIngredient ; owl:someValuesFrom :FishSauceIngredient ] ,\n        [ a owl:Restriction ; owl:onProperty :hasCountryOfOrigin ; owl:hasValue :Thailand ] ;\n    rdfs:label \"green curry\"@en , \"groene curry\"@nl ;\n    skos:altLabel \"kaeng khiao wan\"@th-Latn .\n\n:RedCurry a owl:Class ;\n    rdfs:subClassOf :NamedCurry ,\n        [ a owl:Restriction ; owl:onProperty :hasBase ; owl:someValuesFrom :CoconutMilkBase ] ,\n        [ a owl:Restriction ; owl:onProperty :hasMainIngredient ; owl:someValuesFrom :PorkIngredient ] ,\n        [ a owl:Restriction ; owl:onProperty :hasMainIngredient ; owl:someValuesFrom :BambooShootIngredient ] ,\n        [ a owl:Restriction ; owl:onProperty :hasMainIngredient ; owl:someValuesFrom :RedCurryPasteIngredient ] ,\n        [ a owl:Restriction ; owl:onProperty :hasMainIngredient ; owl:someValuesFrom :FishSauceIngredient ] ,\n        [ a owl:Restriction ; owl:onProperty :hasCountryOfOrigin ; owl:hasValue :Thailand ] ;\n    rdfs:label \"red curry\"@en , \"rode curry\"@nl ;\n    skos:altLabel \"kaeng phet\"@th-Latn .\n\n:MassamanCurry a owl:Class ;\n    rdfs:subClassOf :NamedCurry ,\n        [ a owl:Restriction ; owl:onProperty :hasBase ; owl:someValuesFrom :CoconutMilkBase ] ,\n        [ a owl:Restriction ; owl:onProperty :hasMainIngredient ; owl:someValuesFrom :BeefIngredient ] ,\n        [ a owl:Restriction ; owl:onProperty :hasMainIngredient ; owl:someValuesFrom :PotatoIngredient ] ,\n        [ a owl:Restriction ; owl:onProperty :hasMainIngredient ; owl:someValuesFrom :PeanutIngredient ] ,\n        [ a owl:Restriction ; owl:onProperty :hasMainIngredient ; owl:someValuesFrom :OnionIngredient ] ,\n        [ a owl:Restriction ; owl:onProperty :hasCountryOfOrigin ; owl:hasValue :Thailand ] ;\n    rdfs:label \"Massaman curry\"@en , \"massaman-curry\"@nl .\n\n:ChickenTikkaMasala a owl:Class ;\n    rdfs:subClassOf :NamedCurry ,\n        [ a owl:Restriction ; owl:onProperty :hasBase ; owl:someValuesFrom :TomatoBase ] ,\n        [ a owl:Restriction ; owl:onProperty :hasMainIngredient ; owl:someValuesFrom :ChickenIngredient ] ,\n        [ a owl:Restriction ; owl:onProperty :hasMainIngredient ; owl:someValuesFrom :CreamIngredient ] ,\n        [ a owl:Restriction ; owl:onProperty :hasMainIngredient ; owl:someValuesFrom :GaramMasalaIngredient ] ,\n        [ a owl:Restriction ; owl:onProperty :hasCountryOfOrigin ; owl:hasValue :UnitedKingdom ] ;\n    rdfs:label \"chicken tikka masala\"@en , \"kip tikka masala\"@nl ;\n    rdfs:comment \"Usually said to have been created in British curry houses.\"@en .\n\n:Korma a owl:Class ;\n    rdfs:subClassOf :NamedCurry ,\n        [ a owl:Restriction ; owl:onProperty :hasBase ; owl:someValuesFrom :YoghurtBase ] ,\n        [ a owl:Restriction ; owl:onProperty :hasMainIngredient ; owl:someValuesFrom :LambIngredient ] ,\n        [ a owl:Restriction ; owl:onProperty :hasMainIngredient ; owl:someValuesFrom :CashewIngredient ] ,\n        [ a owl:Restriction ; owl:onProperty :hasMainIngredient ; owl:someValuesFrom :AlmondIngredient ] ,\n        [ a owl:Restriction ; owl:onProperty :hasMainIngredient ; owl:someValuesFrom :CreamIngredient ] ,\n        [ a owl:Restriction ; owl:onProperty :hasCountryOfOrigin ; owl:hasValue :India ] ;\n    rdfs:label \"korma\"@en , \"korma\"@nl ;\n    skos:altLabel \"qorma\"@en ;\n    rdfs:comment \"A mild braise in yoghurt, thickened with ground nuts.\"@en .\n\n:Vindaloo a owl:Class ;\n    rdfs:subClassOf :NamedCurry ,\n        [ a owl:Restriction ; owl:onProperty :hasBase ; owl:someValuesFrom :TomatoBase ] ,\n        [ a owl:Restriction ; owl:onProperty :hasMainIngredient ; owl:someValuesFrom :PorkIngredient ] ,\n        [ a owl:Restriction ; owl:onProperty :hasMainIngredient ; owl:someValuesFrom :ChilliIngredient ] ,\n        [ a owl:Restriction ; owl:onProperty :hasMainIngredient ; owl:someValuesFrom :PotatoIngredient ] ,\n        [ a owl:Restriction ; owl:onProperty :hasCountryOfOrigin ; owl:hasValue :India ] ;\n    rdfs:label \"vindaloo\"@en , \"vindaloo\"@nl ;\n    rdfs:comment \"Goan, from the Portuguese carne de vinha d'alhos; British versions add potato.\"@en .\n\n:DalTadka a owl:Class ;\n    rdfs:subClassOf :NamedCurry ,\n        [ a owl:Restriction ; owl:onProperty :hasBase ; owl:someValuesFrom :LentilBase ] ,\n        [ a owl:Restriction ; owl:onProperty :hasMainIngredient ; owl:someValuesFrom :OnionIngredient ] ,\n        [ a owl:Restriction ; owl:onProperty :hasMainIngredient ; owl:someValuesFrom :GheeIngredient ] ,\n        [ a owl:Restriction ; owl:onProperty :hasMainIngredient ; owl:someValuesFrom :TurmericIngredient ] ,\n        [ a owl:Restriction ; owl:onProperty :hasMainIngredient ; owl:someValuesFrom :CuminIngredient ] ,\n        [ a owl:Restriction ; owl:onProperty :hasCountryOfOrigin ; owl:hasValue :India ] ;\n    rdfs:label \"dal tadka\"@en , \"dal tadka\"@nl ;\n    rdfs:comment \"Lentils finished with spices fried in ghee (the tadka).\"@en .\n\n:PaneerButterMasala a owl:Class ;\n    rdfs:subClassOf :NamedCurry ,\n        [ a owl:Restriction ; owl:onProperty :hasBase ; owl:someValuesFrom :TomatoBase ] ,\n        [ a owl:Restriction ; owl:onProperty :hasMainIngredient ; owl:someValuesFrom :PaneerIngredient ] ,\n        [ a owl:Restriction ; owl:onProperty :hasMainIngredient ; owl:someValuesFrom :ButterIngredient ] ,\n        [ a owl:Restriction ; owl:onProperty :hasMainIngredient ; owl:someValuesFrom :CashewIngredient ] ,\n        [ a owl:Restriction ; owl:onProperty :hasMainIngredient ; owl:someValuesFrom :GaramMasalaIngredient ] ,\n        [ a owl:Restriction ; owl:onProperty :hasCountryOfOrigin ; owl:hasValue :India ] ;\n    rdfs:label \"paneer butter masala\"@en , \"paneer butter masala\"@nl ;\n    skos:altLabel \"paneer makhani\"@en .\n\n:JapaneseCurry a owl:Class ;\n    rdfs:subClassOf :NamedCurry ,\n        [ a owl:Restriction ; owl:onProperty :hasBase ; owl:someValuesFrom :RouxBase ] ,\n        [ a owl:Restriction ; owl:onProperty :hasMainIngredient ; owl:someValuesFrom :BeefIngredient ] ,\n        [ a owl:Restriction ; owl:onProperty :hasMainIngredient ; owl:someValuesFrom :PotatoIngredient ] ,\n        [ a owl:Restriction ; owl:onProperty :hasMainIngredient ; owl:someValuesFrom :CarrotIngredient ] ,\n        [ a owl:Restriction ; owl:onProperty :hasMainIngredient ; owl:someValuesFrom :OnionIngredient ] ,\n        [ a owl:Restriction ; owl:onProperty :hasCountryOfOrigin ; owl:hasValue :Japan ] ;\n    rdfs:label \"Japanese curry\"@en , \"Japanse curry\"@nl ;\n    skos:altLabel \"karē\"@en , \"kare raisu\"@en .\n\n[] a owl:AllDisjointClasses ;\n    owl:members ( :GreenCurry :RedCurry :MassamanCurry :ChickenTikkaMasala :Korma\n                  :Vindaloo :DalTadka :PaneerButterMasala :JapaneseCurry ) .\n\n# ----------------------------------------------------------- defined classes\n# Necessary and sufficient conditions (owl:equivalentClass): a reasoner puts\n# every curry that meets them into the class. A SPARQL engine without a\n# reasoner sees only what is written here.\n\n:MeatyCurry a owl:Class ; rdfs:subClassOf :Curry ;\n    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( :Curry\n        [ a owl:Restriction ; owl:onProperty :hasIngredient ; owl:someValuesFrom :MeatIngredient ] ) ] ;\n    rdfs:label \"meaty curry\"@en , \"curry met vlees\"@nl .\n\n:DairyCurry a owl:Class ; rdfs:subClassOf :Curry ;\n    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( :Curry\n        [ a owl:Restriction ; owl:onProperty :hasIngredient ; owl:someValuesFrom :DairyIngredient ] ) ] ;\n    rdfs:label \"dairy curry\"@en , \"curry met zuivel\"@nl .\n\n:NutCurry a owl:Class ; rdfs:subClassOf :Curry ;\n    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( :Curry\n        [ a owl:Restriction ; owl:onProperty :hasIngredient ; owl:someValuesFrom :NutIngredient ] ) ] ;\n    rdfs:label \"nut curry\"@en , \"curry met noten\"@nl .\n\n:GlutenCurry a owl:Class ; rdfs:subClassOf :Curry ;\n    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( :Curry\n        [ a owl:Restriction ; owl:onProperty :hasIngredient ; owl:someValuesFrom :GrainIngredient ] ) ] ;\n    rdfs:label \"curry with gluten\"@en , \"curry met gluten\"@nl .\n\n:VegetarianCurry a owl:Class ; rdfs:subClassOf :Curry ;\n    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( :Curry\n        [ a owl:Restriction ; owl:onProperty :hasIngredient ; owl:allValuesFrom\n            [ a owl:Class ; owl:complementOf [ a owl:Class ; owl:unionOf ( :MeatIngredient :SeafoodIngredient ) ] ] ] ) ] ;\n    rdfs:label \"vegetarian curry\"@en , \"vegetarische curry\"@nl ;\n    rdfs:comment \"A curry all of whose ingredients are neither meat nor seafood.\"@en .\n";
